// limiter.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. rate must be > 0 and burst must be >= 1.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst < 1 {
		return nil, errors.New("ratelimit: burst must be >= 1")
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   now,
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
